const e="clackamas-county-fair-talent-search",c=2026,t="Built from the 2026 Rules and Regulations (28 rules plus prize list). The document prints no judging marks, no ranks or points, no venue address, no contact person or phone and no fee amount beyond 'no entry fee'. Prizes are gift cards sponsored by a music retailer; the amounts are kept as Variables. The entry application itself is not part of the document.",a={Title:"Rules & Criteria",Subtitle:"Clackamas County Fair Talent Search 2026: auditions on {{AuditionDate}} and finals on {{FinalsDate}} for Children's, Youth and Adult divisions.",NoticeTitle:"Please Read Before Registering",Notice:"Applications must reach the fair office by {{ApplicationDeadline}}. Submitting an application does not guarantee acceptance; the audition committee must approve every act before it performs on stage.",Notes:["Please read all the rules and regulations before submitting your application.","No entry fee is required to apply."],Sections:[{Key:"general",Title:"General",Items:["Entrants must follow all rules and regulations or be removed from the competition.","The fair and the Talent Search Audition Committee may remove any entrant who does not follow the rules, or who refuses the instructions of security or talent competition officials.","Submitting an entry form or meeting the requirements does not ensure acceptance into the competition.","Audition Committee approval is required before performing on stage.","The fair and the committee have sole authority over selecting acts, scheduling them, and controlling stage sets, sound, lights, power and master volume.","All acts perform under the lighting and sound system provided by the fair. The sound is scaled to the venue and the reasonable needs of the contest. The stage manager has absolute control over the system.","No change to stage acts, instruments, sound or lights may be made without prior approval from the Talent Contest Stage Manager. An unauthorised change means the act forfeits its opportunity.","The fair and the contest are not responsible for theft, damage or injury to persons, instruments, props, costumes or clothing before, during or after the performance. This is the sole responsibility of the performing act.","The fair and the contest are not responsible for transport, meals or lodging costs of any contestant.","The contest may be recorded for promotion. Acts give the fair and its sponsors the right to use the recordings to promote the contest in future years, with no further payment. Entrants may opt out by writing their objection on the entry form.","The Talent Search Contest Committee has the right of final decision on any matter the rules do not cover.","Fair management may change these rules without notice.","Auditions are held on {{AuditionDate}}. An additional audition date may be added if many applications are received.","The finals are held on {{FinalsDate}} and consist of the audition finalists from the Children's, Youth and Adult divisions."]},{Key:"eligibility",Title:"Eligibility",Items:["There are three age divisions: Children's (ages 5-9), Youth (ages 10-17) and Adult (ages 18 and older).","The Children's, Youth and Adult divisions do not compete against each other.","The fair accepts entries only from contestants who live in the State of Oregon.","Employees and immediate family members of the fair, its co-sponsors and the Talent Search Audition Committee staff cannot compete.","A contestant who has won first place at the Clackamas County Fair Talent Search cannot compete in the same age division for the following two years.","A contestant may submit only one application and may appear in only one act.","Dance studios may register members as singles and as groups, but each entrant is limited to two tryouts, one as a solo act and one with a group. If chosen in both at the auditions, the participant must choose one act for the final competition.","For a group, the oldest member's age decides the division. Participants must perform in the division assigned by the Talent Search Coordinator and the Fair Director."]},{Key:"registration",Title:"How to register",Items:["Any act, individual performer or agency must send an application to the fair office on or before {{ApplicationDeadline}}, online or delivered to the office.","If delivered in person, the office is open until 5:00 PM.","Incomplete entry forms may not be accepted by the committee.","After the fair office receives the application, the application and the piece listed cannot be changed without prior approval.","No video submissions are accepted. All tryouts are done in person."]},{Key:"fees",Title:"Fees",Items:["Entry fee: {{EntryFee}}."]},{Key:"dates",Title:"Dates",Items:["Application deadline: {{ApplicationDeadline}}.","Audition: {{AuditionDate}}.","Finals: {{FinalsDate}}."]},{Key:"levels",Title:"Rounds and qualification",Items:["Acts go through auditions and then the finals. Each contestant must perform in the assigned round; an act that does not perform in a round loses the right to advance to the next round.","Performers use the same song or act at every level of competition, from auditions through finals. The piece cannot be changed during the competition.","If a qualified contestant or group cannot appear, the act forfeits its place and no substitution is allowed. The empty time slot goes to the first available act on the audition committee's alternate list.","The top placing Clackamas County resident or residents in the Children's, Youth and Adult divisions may qualify for the Oregon State Fair Talent Search Competition. The act performed at the county fair must be the act performed at the state competition.","If a winner cannot attend the Oregon State Fair Talent Search, the runner-up from Clackamas County in that division may take the winner's place."]},{Key:"conduct",Title:"Performance rules",Items:["Vocal acts may use a recorded accompaniment with vocal background, but no lead vocals may be on the track.","Accompaniment should be in a compatible format. A single track is preferred. CDs with background tracks are also accepted if available.","If accompaniment is played from a cell phone, tablet or similar device, the performer must provide a person who knows the device to help the sound crew run it during the audition and performances.","A singer who arrives with unacceptable accompaniment must sing the piece without accompaniment (a cappella).","Lip-sync performances are not allowed.","An act must not be longer than 5 minutes.","Vocal contestants or acts that use more than three single instruments or full drum sets are not accepted.","Baton twirlers and similar acts that use batons, machetes, knives and the like are not accepted.","No fire, smoke or smoke effects are allowed on stage at any time."]},{Key:"judging",Title:"Selection criteria",Items:["The committee considers these selection criteria: appropriateness for fair audiences; capability of production at this talent contest facility; originality, creativity and overall talent; appearance; and an act that does not exceed 5 minutes.","The decision of the judges is final."]},{Key:"prizes",Title:"Prizes",Items:["Prizes are sponsored by {{PrizeSponsor}} and are gift cards for first, second and third place in each division: Children's {{ChildrenPrizes}}; Youth {{YouthPrizes}}; Adult {{AdultPrizes}}.","In the Children's Division the top placing contestants receive prizes and the other finalists receive participation ribbons. Prizes are also awarded for each placement in the Youth and Adult divisions.","Prizes vary with the age, division and placement of the contestants.","Each contestant selected for the finals receives fair admission. Adult and Youth contestants aged 16 and older get one admission ticket for the performance day for each member of the act.","Child and Youth contestants aged 7-15 get one admission ticket for the performance day for each member of the act and one more ticket for a parent or chaperone.","Child contestants aged 6 and under have free admission and get one ticket for a parent or chaperone on the day of participation."]}],Documents:[{Title:"2026 Talent Search Rules and Regulations (PDF)",Url:"https://clackamascountyfair.com/wp-content/uploads/2026/04/2026-Rules-Prizes-Clackamas-County-Talent-Competition.pdf"}]},o=[{ParticipantType:"Team",Source:"Rule 11",Sections:{About:null,TimeAndFormat:null,Rules:["The age of the oldest member decides the division of a group act."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- The age of the oldest member decides the division of a group act.`}],n=[],i=[],s=[],r=[{Key:"AuditionDate",Kind:"date",Label:"Audition date",Value:"2026-06-23",Source:"Rules p.1 (Tuesday evening; another date may be added)"},{Key:"ApplicationDeadline",Kind:"date",Label:"Last date to apply",Value:"2026-06-15",Source:"Rule 7"},{Key:"FinalsDate",Kind:"date",Label:"Finals date",Value:"2026-08-22",Source:"Rule 23"},{Key:"EntryFee",Kind:"fee",Label:"Entry fee",Value:"No entry fee",Source:"Rule 2"},{Key:"PrizeSponsor",Kind:"text",Label:"Prize sponsor",Value:"Canby Music",Source:"Rules p.1"},{Key:"ChildrenPrizes",Kind:"prize",Label:"Children's Division prizes",Value:"$100, $50 and $25 gift cards",Source:"Rules p.1"},{Key:"YouthPrizes",Kind:"prize",Label:"Youth Division prizes",Value:"$200, $100 and $50 gift cards",Source:"Rules p.1"},{Key:"AdultPrizes",Kind:"prize",Label:"Adult Division prizes",Value:"$500, $250 and $125 gift cards",Source:"Rules p.1"}],l=[{Claim:"Rules, eligibility, dates, prizes and admission rules are taken from the fair's own 2026 rules document.",SourceType:"Primary - the event's own rules document",Source:"Clackamas County Talent Search 2026 Rules and Regulations",Url:"https://clackamascountyfair.com/wp-content/uploads/2026/04/2026-Rules-Prizes-Clackamas-County-Talent-Competition.pdf"}],d={TemplateKey:e,Year:2026,Note:t,Page:a,ParticipantTypes:o,AgeGroups:n,Competitions:i,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{n as AgeGroups,s as CompetitionAgeGroups,i as Competitions,l as Evidence,t as Note,a as Page,o as ParticipantTypes,e as TemplateKey,r as Variables,c as Year,d as default};
